async function pageFunction(context){
const out=await context.page.evaluate(()=>{const element=document.querySelector('.product');if(!element)throw Error('Missing owned product');
const keys=['case_id','sku','name','price_minor','currency'];const row={};for(const key of keys){const value=element.getAttribute('data-'+key.replaceAll('_','-'));row[key]=key==='price_minor'?Number(value):value;}return row;});
const now=performance.now(),data=context.request.userData,pool=context.crawler?.autoscaledPool;
const scalar=value=>Number.isInteger(value)&&value>=1&&value<=10?value:null;
const duration=(start)=>Number.isFinite(start)&&start<=now?now-start:null;
out.duration_ms=duration(data.pilot_started_ms);out.elapsed_ms=duration(data.pilot_origin_ms);
out.native_active_tasks_start=scalar(data.native_active_tasks_start);out.native_desired_tasks_start=scalar(data.native_desired_tasks_start);
out.native_active_tasks_end=scalar(pool?.currentConcurrency);out.native_desired_tasks_end=scalar(pool?.desiredConcurrency);return out;}

